class TestExtractCallName:
    def test_simple_name(self):
        tree = ast.parse("foo()")
        call = tree.body[0].value  # type: ignore[attr-defined]
        assert _extract_call_name(call) == "foo"

    def test_attribute_call(self):
        tree = ast.parse("obj.method()")
        call = tree.body[0].value  # type: ignore[attr-defined]
        result = _extract_call_name(call)
        assert result is not None
        assert "method" in result

    def test_nested_attribute(self):
        tree = ast.parse("a.b.c()")
        call = tree.body[0].value  # type: ignore[attr-defined]
        result = _extract_call_name(call)
        assert result is not None
        assert "c" in result


class TestFindFuncNode:
    def test_finds_function(self, tmp_path):
        src = tmp_path / "mod.py"
        src.write_text("def foo():\n    pass\ndef bar():\n    pass\n")
        node = _find_func_node(str(src), "bar")
        assert node is not None
        assert node.name == "bar"

    def test_not_found(self, tmp_path):
        src = tmp_path / "mod.py"
        src.write_text("def foo(): pass\n")
        assert _find_func_node(str(src), "nonexistent") is None

    def test_missing_file(self):
        assert _find_func_node("/nonexistent/file.py", "func") is None


